Chapitre 3 : Continuité
Programme de résolution de l'équation
Soit la fonction f : f(x) = x3 + x - 3. On admet que f admet un unique solution x0 dans
l'intervalle [1,2]. Le programme suivant permet de déterminer une valeur approchée à 10 -2
près de x 0.
Program Dichotomie ;
Uses Wincrt ;
Var a,b:Real; n,c:integer;
Function f(x : Real) : Real;
begin
f:= x*x*x+x-3 end;
Function Dicotomie(a,b:Real;n:integer): Real;
Var m ,fm: Real; k:integer;s;boolean;
Begin
s:=f(a)<0;
for k:=1 to n-1 do
begin
m:=(a+b)/2;fm:=f(m);
if fm=0 then
begin
dicotomie:=m;
exit
end;
if s=(fm<0) then a:=m else b:=m
end;
dicotomie:=(a+b)/2
End;
Begin
clrscr;
writeln(' ****** Résolution de l''équation x3+x-3 = 0 dans [1,2] par DICHOTOMIE
******');
repeat
write ('Nombre d''_tapes : '); Readln(n);writeln;
write ('Nombre de chiffres après la virgule : '); Readln(c);writeln;
until (n>0) and (c>0);
a:=1;b:=2;
Writeln (' La valeur approchée de la solution xo de l''équation x3+x-3 = 0 a 10-',c,' près
est= ');
write(' 	x0 = ' ,dicotomie(a, b, n) :0:c) ;
End.
