program Integration_Rectangles;
uses wincrt ;
var a,b:real;n:integer;
function f(x:real):real; {Lafonction à integrer}
begin f:=1.0 /(1.0+x*x) end;
function Rectangles(a,b:real;n:integer):real;
var k:integer;
h,x,somme:real;
begin
somme:=0.0;
h:=(b-a)/n;
x:=a+h/2.0;
for k:=0 to n-1 do
begin
somme:=somme+f(x);
x:=x+h;
end;
Rectangles:=somme*h
end;
{Le programme principal **********************************}
begin
clrscr; write('Intégration par la méthode des rectangles');
write('Borne inférieure (a) " ');
read(a);
writeln;
repeat
write('Borne supérieure (b) : ');
read(b);
writeln;
until b>a;
repeat
write('Nombre d’intervalles : ');
